const HARI = Array.from({ length: 31 }, (_, i) => i + 1);

const rp = (n) => "Rp " + Math.round(n || 0).toLocaleString("id-ID");
const rpd = (n) => "Rp" + Math.round(n || 0).toLocaleString("id-ID");
const rpk = (n) => {
  const a = Math.abs(n || 0);
  if (a >= 1e9) return (n / 1e9).toFixed(2) + " M";
  if (a >= 1e6) return (n / 1e6).toFixed(1) + " jt";
  if (a >= 1e3) return Math.round(n / 1e3) + " rb";
  return Math.round(n || 0).toString();
};
const num = (n, d = 2) => {
  const v = Math.round((n || 0) * 10 ** d) / 10 ** d;
  return v.toLocaleString("id-ID");
};
const pct = (n) => (n * 100).toFixed(1) + "%";
const sum = (a) => a.reduce((x, y) => x + (y || 0), 0);
