// Dipakai SEMUA tombol "Unduh Excel" di berbagai halaman -- satu fungsi
// bersama, supaya nama berkas, format angka, dan pesan gagalnya konsisten
// di mana pun dipakai, bukannya ditulis ulang beda-beda tiap halaman.
//
// - judulKolom: larik nama kolom, jadi baris pertama berkasnya.
// - baris: larik per baris, tiap baris larik nilai SEJAJAR dengan
//   judulKolom. Untuk kolom rupiah/angka, kirim ANGKA ASLI (number JS),
//   BUKAN string berformat ("Rp 50.000") -- xlsx menebak jenis tiap sel
//   dari tipe datanya, jadi angka asli otomatis jadi sel angka di Excel
//   (bisa dijumlah), sedangkan string apa pun jadi sel teks biasa.
// - judulLembar: nama tab sheet-nya, dirapikan otomatis kalau ada
//   karakter yang tidak boleh dipakai Excel (: \ / ? * [ ]) atau kepanjangan.
//
// CATATAN JUJUR: pustaka "xlsx" yang dipakai proyek ini (versi gratis)
// TIDAK BISA menulis format tebal ke berkas -- sudah dicoba langsung,
// hasilnya baris judul tetap tampil polos di Excel walau kodenya
// "disuruh" tebal. Baris judul tetap ada di baris pertama seperti biasa,
// cuma tidak tebal. Kalau nanti mau beneran tebal, perlu pustaka tambahan
// (dibahas terpisah, belum dipasang).
//
// Mengembalikan true kalau berhasil, false kalau unduhannya gagal/
// diblokir peramban -- pemanggilnya yang menampilkan pesannya sendiri
// lewat pesan(), supaya fungsi ini tidak perlu tahu soal sistem toast.
//
// Untuk halaman yang punya lebih dari satu tabel berbeda sekaligus (mis.
// Penggajian: tanggal 1, tanggal 16, rekap), pakai unduhExcelBanyakLembar()
// di bawah -- satu berkas, tiap tabel jadi sheet-nya sendiri.
// Dipakai unduhExcel() dan unduhExcelBanyakLembar() di bawah -- satu sheet
// dari judulKolom+baris, dengan lebar kolom otomatis mengikuti isi
// terpanjang supaya tidak perlu dilebarkan manual tiap kali dibuka.
function buatLembarExcel(judulKolom, baris) {
  const grid = [judulKolom, ...baris];
  const ws = XLSX.utils.aoa_to_sheet(grid);
  ws["!cols"] = judulKolom.map((_, i) => {
    const terpanjang = Math.max(...grid.map((b) => String(b[i] ?? "").length));
    return { wch: Math.min(40, Math.max(8, terpanjang + 2)) };
  });
  return ws;
}

// Dipakai unduhExcel() dan unduhExcelBanyakLembar() -- ubah workbook jadi
// berkas .xlsx dan picu unduhannya. Balikan true/false, lihat catatan di
// unduhExcel() soal kenapa fungsi ini tidak menampilkan pesannya sendiri.
function unduhWorkbook(wb, namaBerkas) {
  try {
    const nama = /\.xlsx$/i.test(namaBerkas) ? namaBerkas : `${namaBerkas}.xlsx`;
    const buf = XLSX.write(wb, { type: "array", bookType: "xlsx" });
    const blob = new Blob([buf], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = nama;
    document.body.appendChild(a); a.click();
    setTimeout(() => { document.body.removeChild(a); URL.revokeObjectURL(url); }, 500);
    return true;
  } catch (e) {
    console.error("[unduhWorkbook] gagal membuat/mengunduh berkas:", e);
    return false;
  }
}

function unduhExcel(namaBerkas, judulKolom, baris, judulLembar = "Sheet1") {
  try {
    const ws = buatLembarExcel(judulKolom, baris);
    const namaLembar = String(judulLembar || "Sheet1").replace(/[:\\/?*[\]]/g, " ").slice(0, 31) || "Sheet1";
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, namaLembar);
    return unduhWorkbook(wb, namaBerkas);
  } catch (e) {
    console.error("[unduhExcel] gagal membuat/mengunduh berkas:", e);
    return false;
  }
}

// Untuk halaman yang punya BEBERAPA tabel berbeda sekaligus (mis. Penggajian:
// tanggal 1, tanggal 16, rekap) -- satu berkas, tiap tabel jadi tab/sheet-nya
// sendiri, supaya tidak perlu mengunduh beberapa berkas terpisah untuk satu
// halaman. "lembar" adalah larik { judulLembar, judulKolom, baris }.
function unduhExcelBanyakLembar(namaBerkas, lembar) {
  try {
    const wb = XLSX.utils.book_new();
    const namaDipakai = new Set();
    lembar.forEach(({ judulLembar, judulKolom, baris }) => {
      let nama = String(judulLembar || "Sheet1").replace(/[:\\/?*[\]]/g, " ").slice(0, 31) || "Sheet1";
      while (namaDipakai.has(nama)) nama = nama.slice(0, 28) + " " + (namaDipakai.size + 1);
      namaDipakai.add(nama);
      XLSX.utils.book_append_sheet(wb, buatLembarExcel(judulKolom, baris), nama);
    });
    return unduhWorkbook(wb, namaBerkas);
  } catch (e) {
    console.error("[unduhExcelBanyakLembar] gagal membuat/mengunduh berkas:", e);
    return false;
  }
}

// Dipakai halaman yang perlu tahu "sedang di HP atau tidak" untuk mengubah
// ALUR (bukan cuma tampilan -- itu cukup lewat @media CSS biasa) -- misalnya
// form pengajuan yang dipecah jadi dua langkah di layar sempit. Batasnya
// sengaja disamakan dengan breakpoint @media (max-width:820px) yang sudah
// dipakai di seluruh CSS aplikasi ini, supaya keduanya konsisten.
function usePonsel() {
  const [ponsel, setPonsel] = useState(() => typeof window !== "undefined" && window.innerWidth <= 820);
  useEffect(() => {
    const cek = () => setPonsel(window.innerWidth <= 820);
    window.addEventListener("resize", cek);
    return () => window.removeEventListener("resize", cek);
  }, []);
  return ponsel;
}

