// Dipakai di alur belanja (Request & Daftar belanja) untuk mengunci STAFF/HEAD
// ke divisinya sendiri. Owner/Purchasing/Finance dan karyawan divisi OTHER
// (marketing dll) dianggap boleh melihat & mengisi semua divisi.
const PERAN_LIHAT_SEMUA_DIVISI = ["OWNER", "PURCHASING", "FINANCE"];
const lihatSemuaDivisi = (peran, aku) => PERAN_LIHAT_SEMUA_DIVISI.includes(peran) || aku.divisi === "OTHER";
const divisiBahan = (b) => (b?.bar ? "BAR" : "FOOD");
const labelDivisi = (d) => (d === "BAR" ? "Bar" : d === "FOOD" ? "Kitchen" : "Lainnya");

// Satu daftar belanja (nota) bisa berisi bahan Bar dan Kitchen sekaligus, dan
// tiap divisi mengecek bagiannya sendiri-sendiri (lihat cekBar/cekFood). Dua
// helper ini dipakai di Request (badge tab) dan NotaBelanja (status, tombol).
function statusDivisiNota(n, db) {
  const adaBar = n.baris.some((b) => divisiBahan(db.bahan[b.itemIdx]) === "BAR");
  const adaFood = n.baris.some((b) => divisiBahan(db.bahan[b.itemIdx]) === "FOOD");
  const barSelesai = !adaBar || !!n.cekBar;
  const foodSelesai = !adaFood || !!n.cekFood;
  return { adaBar, adaFood, barSelesai, foodSelesai, selesai: barSelesai && foodSelesai };
}
// Apakah orang ini masih punya bagian yang perlu dicek di nota n?
const perluCekSaya = (n, peran, aku, db) => {
  if (n.status !== "Menunggu dicek") return false;
  const s = statusDivisiNota(n, db);
  if (lihatSemuaDivisi(peran, aku)) return !s.selesai;
  if (aku.divisi === "BAR") return s.adaBar && !s.barSelesai;
  if (aku.divisi === "FOOD") return s.adaFood && !s.foodSelesai;
  return false;
};

/* ============================================================
   PERIODE — arsip per bulan
   ============================================================ */
const BULAN = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
const namaPeriode = (p) => {
  const [t, b] = p.split("-");
  return `${BULAN[parseInt(b) - 1]} ${t}`;
};
const jumlahHari = (p) => {
  const [t, b] = p.split("-").map(Number);
  return new Date(t, b, 0).getDate();
};
const periodeSebelum = (p) => {
  const [t, b] = p.split("-").map(Number);
  return b === 1 ? `${t - 1}-12` : `${t}-${String(b - 1).padStart(2, "0")}`;
};

function petikAktif(db) {
  return {
    bahan: db.bahan.map((b) => ({ hari: b.hari, awal: b.awal, fisik: b.fisik, fisik16: b.fisik16 || 0, ket: b.ket })),
    menu: db.menu.map((m) => ({ d: m.d, o: m.o })),
    jadwal: db.jadwal,
    lembur: db.lembur || {},
    service: db.service || 0,
    dasarService: db.dasarService || "hari",
    laporan: db.laporan || laporanKosong(),
  };
}

function gantiPeriode(db, baru) {
  if (baru === db.aktif) return db;
  const arsip = { ...db.arsip, [db.aktif]: petikAktif(db) };
  const isi = arsip[baru];
  const lalu = arsip[periodeSebelum(baru)];

  const bahan = db.bahan.map((b, i) =>
    isi ? { ...b, ...isi.bahan[i] }
      : { ...b, hari: [], ket: "", fisik: 0, fisik16: 0, awal: lalu ? lalu.bahan[i]?.fisik || 0 : 0 });
  const menu = db.menu.map((m, i) =>
    isi ? { ...m, ...isi.menu[i] } : { ...m, d: Array(31).fill(0), o: Array(31).fill(0) });

  return { ...db, arsip, aktif: baru, bahan, menu,
    jadwal: isi ? isi.jadwal : {}, lembur: isi ? isi.lembur || {} : {},
    service: isi ? isi.service : 0, dasarService: isi ? isi.dasarService || "hari" : db.dasarService || "hari",
    laporan: isi ? isi.laporan || laporanKosong() : laporanKosong() };
}

function PilihPeriode({ db, pindahPeriode }) {
  const [t, b] = db.aktif.split("-").map(Number);
  const [sibuk, setSibuk] = useState(false);
  const pindah = async (p) => {
    if (p === db.aktif || sibuk) return;
    setSibuk(true);
    await pindahPeriode(p);
    setSibuk(false);
  };
  return (
    <div className="ks-periode">
      <select value={b} disabled={sibuk} onChange={(e) => pindah(`${t}-${String(+e.target.value).padStart(2, "0")}`)}>
        {BULAN.map((n, i) => <option key={n} value={i + 1}>{n}</option>)}
      </select>
      <select value={t} disabled={sibuk} onChange={(e) => pindah(`${e.target.value}-${String(b).padStart(2, "0")}`)}>
        {[2025, 2026, 2027].map((x) => <option key={x} value={x}>{x}</option>)}
      </select>
      <PenandaTipis aktif={sibuk} />
    </div>
  );
}

