/* ============================================================
   PENGURUTAN
   ============================================================ */
function urutkan(arr, mode, teks, angka) {
  const a = [...arr];
  if (mode === "az") return a.sort((x, y) => teks(x).localeCompare(teks(y)));
  if (mode === "za") return a.sort((x, y) => teks(y).localeCompare(teks(x)));
  if (mode === "kecil") return a.sort((x, y) => angka(x) - angka(y));
  return a.sort((x, y) => angka(y) - angka(x));
}

function Urut({ nilai, set, labelAngka = "Nilai" }) {
  return (
    <select value={nilai} onChange={(e) => set(e.target.value)} className="ks-mini-input" title="Urutan tampilan">
      <option value="az">A → Z</option>
      <option value="za">Z → A</option>
      <option value="besar">{labelAngka} terbesar</option>
      <option value="kecil">{labelAngka} terkecil</option>
    </select>
  );
}

/* ============================================================
   PENCARI BAHAN — pengganti dropdown panjang
   ============================================================ */
function CariBahan({ db, H, nilai, set, placeholder = "Ketik nama bahan", hanyaDivisi = null }) {
  const [teks, setTeks] = useState("");
  const [buka, setBuka] = useState(false);
  // Jaga-jaga terhadap "klik hantu": begitu bahan dipilih, tombol X (hapus pilihan)
  // langsung muncul persis di posisi tombol yang baru diklik — kadang sisa klik yang
  // sama nyasar ke tombol baru itu dan langsung menghapus pilihan lagi. Klik pada
  // tombol X diabaikan kalau terjadi sangat cepat setelah sebuah bahan baru dipilih.
  const waktuPilih = useRef(0);
  const terpilih = nilai !== "" && nilai !== undefined ? db.bahan[nilai] : null;

  // hanyaDivisi: kalau diisi ("BAR"/"FOOD"), bahan divisi lain tidak muncul di
  // pencarian sama sekali — dipakai form "Ajukan bahan" supaya karyawan cuma
  // bisa mengajukan bahan divisinya sendiri.
  const hasil = teks.trim().length < 1 ? [] : db.bahan
    .map((b, i) => ({ ...b, i }))
    .filter((b) => !hanyaDivisi || divisiBahan(b) === hanyaDivisi)
    .filter((b) => b.n.toLowerCase().includes(teks.toLowerCase()))
    .slice(0, 8);

  if (terpilih && !buka) {
    const infoStok = H?.bahan?.[nilai];
    return (
      <div className="ks-terpilih">
        <div>
          <b>{rapi(terpilih.n)}</b>
          <div className="ks-sub">
            {infoStok ? `sisa ${num(infoStok.seharusnya, 0)} ` : ""}{terpilih.u.toLowerCase()} · {terpilih.bar ? "Bar" : "Kitchen"}
          </div>
        </div>
        <button className="ks-ikon" onClick={() => {
          if (Date.now() - waktuPilih.current < 400) return;
          set(""); setTeks(""); setBuka(true);
        }}><X size={15} /></button>
      </div>
    );
  }

  return (
    <div className="ks-cari-bahan">
      <div className="ks-cari lebar">
        <Search size={14} />
        <input value={teks} autoFocus placeholder={placeholder} onChange={(e) => { setTeks(e.target.value); setBuka(true); }} />
      </div>
      {hasil.length > 0 && (
        <div className="ks-hasil-cari">
          {hasil.map((b) => (
            // onMouseDown, BUKAN onClick -- kotak isian di atas kehilangan fokus
            // begitu jari/pointer menyentuh baris ini (perilaku bawaan peramban).
            // Di HP itu menutup papan ketik SEBELUM jari diangkat, layar berubah
            // tinggi, baris ini bergeser posisi, dan ketukan (mouseup/click)
            // akhirnya mendarat di tempat yang sudah kosong. onMouseDown terjadi
            // lebih dulu -- preventDefault() menahan kotak isian tetap fokus
            // sebentar lagi supaya pilihannya sempat tercatat sebelum semua itu
            // terjadi.
            <button key={b.i} type="button" onMouseDown={(e) => {
              e.preventDefault();
              waktuPilih.current = Date.now();
              set(String(b.i)); setBuka(false); setTeks("");
            }}>
              <span><b>{rapi(b.n)}</b><span className="ks-sub"> · {b.bar ? "Bar" : "Kitchen"}</span></span>
              <span className={"n ks-sub" + (H.bahan[b.i].seharusnya <= 0 ? " minus" : "")}>{num(H.bahan[b.i].seharusnya, 0)} {b.u.toLowerCase()}</span>
            </button>
          ))}
        </div>
      )}
      {teks.trim().length >= 1 && hasil.length === 0 && <div className="ks-sub" style={{ padding: "8px 4px" }}>Tidak ada bahan yang cocok.</div>}
    </div>
  );
}

/* ============================================================
   NOTIFIKASI — disesuaikan dengan peran
   ============================================================ */
function bikinNotif(db, H, aku, peran, absen) {
  const n = [];
  const hariIni = new Date().toISOString().slice(0, 10);
  const req = db.request || [];
  const MOD = (db.modul || MODUL_AWAL).filter((m) => m.aktif !== false);
  const untukKu = MOD.filter((m) => m.target === "SEMUA" || m.target === aku.divisi || (m.target === "PILIH" && (m.pilih || []).includes(aku.id)));
  const siklusKini = SIKLUS[SIKLUS.length - 2].id;

  const tugasKuis = untukKu.filter((m) => !(db.kuis || []).some((x) => x.karyawanId === aku.id && x.modul === m.id && x.siklus === siklusKini));
  if (tugasKuis.length) n.push({ hal: "kuis", jenis: tugasKuis.some((m) => m.deadline && m.deadline < hariIni) ? "merah" : "kuning",
    teks: `${tugasKuis.length} asesmen belum kamu kerjakan siklus ini`, detail: tugasKuis.map((m) => m.nama).join(", ") });

  const rekanKu = db.karyawan.filter((k) => k.role !== "OWNER" && k.status !== "Nonaktif" && k.id !== aku.id && k.divisi === aku.divisi);
  const peerBelum = rekanKu.filter((k) => !(db.peer || []).some((p) => p.siklus === siklusKini && p.dariId === aku.id && p.keId === k.id));
  if (peerBelum.length) n.push({ hal: "peer", jenis: "kuning", teks: `${peerBelum.length} peer review belum kamu isi`, detail: peerBelum.map((k) => k.nama).join(", ") });

  const shiftKu = Object.keys(db.jadwal || {}).filter((k) => k.startsWith(aku.id + "-")).length;
  if (!shiftKu && peran === "STAFF") n.push({ hal: "jadwal", jenis: "kuning", teks: "Kamu belum punya jadwal shift bulan ini", detail: "Hubungi head divisimu." });

  const notaCek = (db.nota || []).filter((x) => x.status === "Menunggu dicek");
  if (notaCek.length) n.push({ hal: "request", jenis: "kuning",
    teks: `${notaCek.length} daftar belanja menunggu dicek`,
    detail: `${sum(notaCek.map((x) => x.baris.length))} bahan perlu dicocokkan dengan barang yang datang` });

  if (["PURCHASING", "OWNER"].includes(peran)) {
    const baru = req.filter((r) => r.status === "Baru");
    if (baru.length) n.push({ hal: "request", jenis: baru.some((r) => r.urgensi === "Mendesak") ? "merah" : "kuning",
      teks: `${baru.length} request belanja menunggu diproses`, detail: `${baru.filter((r) => r.urgensi === "Mendesak").length} bertanda mendesak` });
    const habis = H.bahan.filter((b) => b.seharusnya <= 0);
    if (habis.length) n.push({ hal: "live", jenis: "merah", teks: `${habis.length} bahan bersaldo nol atau minus`, detail: habis.slice(0, 4).map((b) => rapi(b.n)).join(", ") });
  }

  if (["HEAD_BAR", "HEAD_KITCHEN", "OWNER"].includes(peran)) {
    const div = divisiPeran(peran);
    const milik = H.bahan.filter((b) => !div || (div === "BAR") === !!b.bar);
    const belumSO = milik.filter((b) => b.fisik == null).length;
    // Makin mendesak kalau bulan yang sedang dibuka itu bulan berjalan
    // sungguhan dan tanggalnya sudah dekat akhir bulan -- supaya pengingat
    // ini tidak menyala sepanjang bulan sejak hari pertama.
    const hariTersisa = db.aktif === periodeSekarang() ? H.akhirBulan - new Date().getDate() : null;
    const mendesak = hariTersisa != null && hariTersisa <= 5;
    if (belumSO) n.push({ hal: "so", jenis: mendesak ? "merah" : "kuning",
      teks: mendesak
        ? `Tinggal ${Math.max(hariTersisa, 0)} hari lagi, ${belumSO} bahan belum dihitung di opname akhir bulan`
        : `${belumSO} bahan belum dihitung di opname akhir bulan`,
      detail: `dari ${milik.length} bahan` });
    const timku = db.karyawan.filter((k) => k.role !== "OWNER" && k.status !== "Nonaktif" && (!div || k.divisi === div));
    const tanpaJadwal = timku.filter((k) => !Object.keys(db.jadwal || {}).some((x) => x.startsWith(k.id + "-")));
    if (tanpaJadwal.length) n.push({ hal: "jadwal", jenis: "kuning", teks: `${tanpaJadwal.length} karyawan belum dijadwalkan`, detail: tanpaJadwal.map((k) => k.nama).join(", ") });
  }

  if (peran === "OWNER") {
    const lewat = db.karyawan.filter((k) => k.status !== "Nonaktif" && (k.akhir || k.kontrakAkhir) && new Date(k.akhir || k.kontrakAkhir) < new Date());
    if (lewat.length) n.push({ hal: "karyawan", jenis: "merah", teks: `${lewat.length} kontrak sudah lewat tanggal`, detail: lewat.map((k) => k.nama).join(", ") });
    const dekat = db.karyawan.filter((k) => {
      const a = k.akhir || k.kontrakAkhir;
      if (!a || k.status === "Nonaktif") return false;
      const s = (new Date(a) - new Date()) / 86400000;
      return s >= 0 && s <= 45;
    });
    if (dekat.length) n.push({ hal: "karyawan", jenis: "kuning", teks: `${dekat.length} kontrak habis dalam 45 hari`, detail: dekat.map((k) => k.nama).join(", ") });
    const gap = H.cogsReal - H.cogsResep;
    if (H.omzet && gap > 0.03) n.push({ hal: "ringkasan", jenis: "merah",
      teks: `COGS real ${pct(H.cogsReal)}, lebih tinggi ${pct(gap)} dari resep`, detail: `selisih setara ${rp(gap * H.omzet)}` });
    const janggal = H.bahan.filter((b) => b.janggal);
    if (janggal.length) n.push({ hal: "bahan", jenis: "kuning", teks: `${janggal.length} bahan satuan belanjanya belum cocok`, detail: janggal.map((b) => rapi(b.n)).join(", ") });
  }

  // Cuti/izin/sakit (lihat CutiIzin) -- "absen" sudah otomatis terbatas sesuai
  // peran lewat RLS "absen: baca", jadi di sini tinggal dipisah per kebutuhan.
  if (absen) {
    if (["HEAD_BAR", "HEAD_KITCHEN", "OWNER"].includes(peran)) {
      const baru = absen.filter((a) => a.status === "Baru" && a.karyawan_id !== aku.id);
      if (baru.length) n.push({ hal: "absen", jenis: "kuning", teks: `${baru.length} pengajuan cuti/izin/sakit menunggu diputus`, detail: "Buka Cuti & izin untuk menyetujui atau menolak." });
    }
    const punyaku = absen.filter((a) => a.karyawan_id === aku.id && a.status !== "Baru" && a.status !== "Dibatalkan" && !a.dilihat);
    if (punyaku.length) n.push({ hal: "absen", jenis: "kuning", teks: `${punyaku.length} pengajuan cuti/izin/sakitmu sudah diputus`, detail: "Buka Cuti & izin untuk melihat balasannya." });
  }
  return n;
}

function Lonceng({ db, H, aku, peran, pergi, absen }) {
  const [buka, setBuka] = useState(false);
  const notif = bikinNotif(db, H, aku, peran, absen);
  const merah = notif.filter((x) => x.jenis === "merah").length;

  return (
    <div className="ks-lonceng">
      <button className="ks-lonceng-tombol" onClick={() => setBuka(!buka)} title="Notifikasi">
        <Bell size={16} />
        {notif.length > 0 && <span className={"ks-lonceng-angka" + (merah ? " merah" : "")}>{notif.length}</span>}
      </button>
      {buka && (
        <>
          <div className="ks-lonceng-tirai" onClick={() => setBuka(false)} />
          <div className="ks-lonceng-panel">
            <div className="ks-lonceng-atas">
              <b>Notifikasi</b>
              <button className="ks-ikon" onClick={() => setBuka(false)}><X size={15} /></button>
            </div>
            {notif.length === 0 ? (
              <div className="ks-kosong">Tidak ada yang perlu ditindaklanjuti. Bagus.</div>
            ) : notif.map((x, i) => (
              <button key={i} className={"ks-notif " + x.jenis} onClick={() => { pergi(x.hal); setBuka(false); }}>
                <span className="ks-notif-titik" />
                <span>
                  <b>{x.teks}</b>
                  <span className="ks-sub">{x.detail}</span>
                </span>
              </button>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

