/* ============================================================
   PEMILIH UKURAN — dipakai di permintaan, daftar belanja, dan pengecekan
   ============================================================ */
function PilihKemasan({ bahan, nama, set, tambahKemasan, ringkas }) {
  const [baru, setBaru] = useState(null);
  const [sibuk, setSibuk] = useState(false);
  const daftar = daftarKemasan(bahan);
  const kini = cariKemasan(bahan, nama) || daftar[0];

  if (baru) {
    return (
      <div className="ks-kemasan-baru">
        <input value={baru.n} placeholder="Nama ukuran, mis. Botol kecil" onChange={(e) => setBaru({ ...baru, n: e.target.value })} disabled={sibuk} />
        <div className="ks-satuan">
          <input type="number" step="any" value={baru.i} placeholder="isi" onChange={(e) => setBaru({ ...baru, i: e.target.value })} disabled={sibuk} />
          <span className="ks-sub">{(bahan.u || "").toLowerCase()} per {baru.n ? baru.n.toLowerCase() : "ukuran"}</span>
        </div>
        <div className="ks-inline">
          {/* tambahKemasan() sekarang memanggil rpc ke Supabase (lihat Request/
              NotaBelanja) -- ditunggu dulu (await) sebelum pindah balik ke
              dropdown, dan kalau gagal (mis. bukan Owner/Purchasing dulu,
              sebelum migrasi 21) tetap di sini, tidak berpura-pura berhasil. */}
          <button className="ks-btn kecil utama" disabled={sibuk} onClick={async () => {
            if (!baru.n.trim() || !(parseFloat(baru.i) > 0)) return;
            setSibuk(true);
            const hasil = await tambahKemasan({ n: baru.n.trim(), i: parseFloat(baru.i) });
            setSibuk(false);
            if (hasil === false) return;
            set(baru.n.trim());
            setBaru(null);
          }}>{sibuk ? "Menyimpan…" : "Simpan ukuran"}</button>
          <button className="ks-btn kecil" onClick={() => setBaru(null)} disabled={sibuk}>Batal</button>
        </div>
      </div>
    );
  }

  return (
    <div className={ringkas ? "" : "ks-satuan"}>
      <select value={kini.n} onChange={(e) => {
        if (e.target.value === "__baru") setBaru({ n: "", i: "" });
        else set(e.target.value);
      }}>
        {daftar.map((k) => (
          <option key={k.n} value={k.n}>{k.dasar ? `${k.n} (satuan stok)` : `${k.n} — ${num(k.i, 0)} ${(bahan.u || "").toLowerCase()}`}</option>
        ))}
        {tambahKemasan && <option value="__baru">+ ukuran baru…</option>}
      </select>
    </div>
  );
}

/* ============================================================
   PENGELOLA UKURAN KEMASAN DI MASTER BAHAN
   ============================================================ */
function ModalKemasan({ bahan, idx, db, simpan, tutup, pesan }) {
  const [daftar, setDaftar] = useState(kemasanArray(bahan.kemasan));

  const simpanSemua = () => {
    const bersih = daftar.filter((x) => x.n.trim() && parseFloat(x.i) > 0)
      .map((x) => ({ n: x.n.trim(), i: parseFloat(x.i) }));
    const nama = bersih.map((x) => x.n.toUpperCase());
    if (new Set(nama).size !== nama.length) { pesan("Ada nama ukuran yang kembar.", "alert"); return false; }
    simpan({ ...db, bahan: db.bahan.map((b, i) => (i === idx ? { ...b, kemasan: bersih } : b)) });
    pesan(`Ukuran kemasan ${rapi(bahan.n)} disimpan.`);
  };

  return (
    <Modal judul={`Ukuran kemasan — ${rapi(bahan.n)}`} tutup={tutup} simpan={simpanSemua}>
      <p className="ks-sub" style={{ marginBottom: 12 }}>
        Stok bahan ini dihitung dalam <b>{(bahan.u || "").toLowerCase()}</b>. Daftarkan setiap ukuran yang biasa dibeli,
        supaya karyawan tinggal memilih dan tidak perlu mengetik angka konversi setiap kali.
      </p>
      <table className="ks-tabel rapat">
        <thead><tr><th>Nama ukuran</th><th className="r">Isi ({(bahan.u || "").toLowerCase()})</th><th></th></tr></thead>
        <tbody>
          {daftar.map((x, i) => (
            <tr key={i}>
              <td><input value={x.n} placeholder="misal: Botol besar" onChange={(e) => setDaftar(daftar.map((y, j) => (j === i ? { ...y, n: e.target.value } : y)))} /></td>
              <td className="r"><input type="number" step="any" value={x.i} onChange={(e) => setDaftar(daftar.map((y, j) => (j === i ? { ...y, i: e.target.value } : y)))} /></td>
              <td className="r"><button className="ks-ikon" onClick={() => setDaftar(daftar.filter((_, j) => j !== i))}><X size={14} /></button></td>
            </tr>
          ))}
        </tbody>
      </table>
      {daftar.length === 0 && <Kosong teks="Belum ada ukuran. Bahan ini hanya bisa diminta dalam satuan stoknya." />}
      <button className="ks-btn" onClick={() => setDaftar([...daftar, { n: "", i: "" }])}><Plus size={14} /> Tambah ukuran</button>
    </Modal>
  );
}

/* ============================================================
   PEMERIKSA KEWAJARAN HARGA SATUAN
   Menangkap salah pilih ukuran pada saat barang dicek, bukan setelah opname.
   ============================================================ */
function cekHargaSatuan(hargaLama, rupiah, qty, isi) {
  const unit = (parseFloat(qty) || 0) * (parseFloat(isi) || 1);
  const rp2 = parseFloat(rupiah) || 0;
  if (!unit || !rp2 || !hargaLama) return null;
  const harga = rp2 / unit;
  const rasio = harga / hargaLama;
  if (rasio > 3 || rasio < 1 / 3) return { harga, hargaLama, rasio };
  return null;
}

