/* ============================================================
   PERHITUNGAN PENGGAJIAN — dipakai halaman Penggajian dan Slip gaji
   ============================================================ */
const DASAR_SERVICE = {
  hari: { label: "Hari masuk", ket: "Sebanding dengan jumlah hari masuk. Sederhana, tapi shift 7 jam dan shift 9 jam dihargai sama." },
  jam: { label: "Jam kerja", ket: "Sebanding dengan total jam kerja. Lebih adil kalau panjang shift berbeda-beda." },
  poin: { label: "Jam kerja × poin jabatan", ket: "Jam kerja dikali poin tiap orang. Dipakai kalau posisi tertentu memang disepakati mendapat porsi lebih besar." },
};

function hitungPenggajian(db) {
  const hariBulan = jumlahHari(db.aktif);
  const lembur = db.lembur || {};
  const jamKerja = parseFloat(db.jamKerja) || 7;
  const dasar = db.dasarService || "hari";
  const kolam = parseFloat(db.service) || 0;

  const aktif = db.karyawan.filter((k) => k.status !== "Nonaktif" && k.role !== "OWNER");
  const penerima = aktif.filter((k) => k.service);

  const bobotDari = (k, r) => {
    const poin = parseFloat(k.poin) || 1;
    if (dasar === "jam") return r.jam;
    if (dasar === "poin") return r.jam * poin;
    return r.shift;
  };
  const totalBobot = sum(penerima.map((k) => bobotDari(k, rekapShift(db, k.id, 1, hariBulan))));

  const tarifLembur = (k) => (k.jenis === "PART"
    ? (parseFloat(k.gaji) || 0) / jamKerja
    : (parseFloat(k.gaji) || 0) / 26 / jamKerja);

  const baris = aktif.map((k) => {
    const r = rekapShift(db, k.id, 1, hariBulan);
    const part = k.jenis === "PART";
    const pokok = part ? (parseFloat(k.gaji) || 0) * r.shift : parseFloat(k.gaji) || 0;
    const tunjangan = part ? 0 : parseFloat(k.tunjangan) || 0;
    const jam = parseFloat(lembur[k.id]) || 0;
    const tarif = tarifLembur(k);
    const uangLembur = tarif * jam;
    const termin1 = pokok + tunjangan + uangLembur;
    const bobot = bobotDari(k, r);
    const porsi = k.service && totalBobot ? bobot / totalBobot : 0;
    const service = kolam * porsi;
    return { ...k, part, hariMasuk: r.shift, jamKerjaAktual: r.jam, komposisi: r.komposisi,
      pokok, tunjangan, jam, tarif, uangLembur, termin1, bobot, porsi, service, total: termin1 + service };
  });

  return { baris, penerima, kolam, totalBobot, dasar, jamKerja, hariBulan,
    t1: sum(baris.map((b) => b.termin1)), t2: sum(baris.map((b) => b.service)) };
}

/* ============================================================
   SLIP GAJI — yang dilihat karyawan tentang dirinya sendiri
   ============================================================ */
function SlipGaji({ db, aku }) {
  const SHIFT = shiftDef(db);
  const G = hitungPenggajian(db);
  const b = G.baris.find((x) => x.id === aku.id);

  if (!b) {
    return (
      <>
        <Head judul="Slip gaji" sub={namaPeriode(db.aktif)} />
        <Kosong teks="Akun ini tidak termasuk dalam daftar penggajian." />
      </>
    );
  }

  const rincian1 = [
    ["Gaji pokok", b.pokok, b.part ? `${rp(b.gaji)} × ${b.hariMasuk} hari masuk` : "penuh sebulan"],
    ["Tunjangan", b.tunjangan, b.part ? "tidak berlaku untuk part time" : "penuh sebulan"],
    ["Lembur", b.uangLembur, b.jam ? `${num(b.jam, 1)} jam × ${rpd(b.tarif)}` : "tidak ada lembur bulan ini"],
  ];

  const dasarTeks = G.dasar === "jam" ? `${b.jamKerjaAktual} jam kerja`
    : G.dasar === "poin" ? `${b.jamKerjaAktual} jam × poin ${num(parseFloat(b.poin) || 1, 2)}`
    : `${b.hariMasuk} hari masuk`;

  return (
    <>
      <Head judul="Slip gaji" sub={`${namaPeriode(db.aktif)} · ganti bulan di atas untuk melihat periode lain`} />

      <div className="ks-slip-kepala">
        <div>
          <div className="ks-slip-nama">{b.nama}</div>
          <div className="ks-sub">{b.posisi} · {b.divisi === "FOOD" ? "Kitchen" : b.divisi === "BAR" ? "Bar" : "Lainnya"}{b.part ? " · part time" : ""}</div>
        </div>
        <div className="r">
          <div className="ks-sub">Periode</div>
          <div className="ks-slip-rek">{namaPeriode(db.aktif)}</div>
        </div>
      </div>

      <div className="ks-kpi">
        <Kpi label="Tanggal 1" nilai={rp(b.termin1)} sub="pokok, tunjangan, lembur" />
        <Kpi label="Tanggal 16" nilai={b.service ? rp(b.service) : "—"} sub={b.service ? "bonus" : "tidak menerima bonus"} />
        <Kpi label="Total bulan ini" nilai={rp(b.total)} sub="sebelum potongan" nada="ok" />
        <Kpi label="Kehadiran" nilai={`${b.hariMasuk} hari`} sub={`${b.jamKerjaAktual} jam kerja`} />
      </div>

      <div className="ks-grid2">
        <Panel judul="Tanggal 1" catatan="Gaji pokok, tunjangan, dan lembur.">
          <table className="ks-tabel">
            <tbody>
              {rincian1.map(([nama, nilai, ket]) => (
                <tr key={nama}>
                  <td>{nama}<div className="ks-sub">{ket}</div></td>
                  <td className="r n">{nilai ? rp(nilai) : "—"}</td>
                </tr>
              ))}
            </tbody>
            <tfoot><tr><td className="r">Diterima tanggal 1</td><td className="r n"><b>{rp(b.termin1)}</b></td></tr></tfoot>
          </table>
        </Panel>

        <Panel judul="Tanggal 16 — bonus" catatan={`Dibagi menurut ${DASAR_SERVICE[G.dasar].label.toLowerCase()}, dan selalu habis terbagi.`}>
          {!b.service ? (
            <Kosong teks="Posisi ini tidak termasuk penerima bonus." />
          ) : (
            <table className="ks-tabel">
              <tbody>
                <tr><td>Uang bonus seluruhnya<div className="ks-sub">dikumpulkan sebulan</div></td><td className="r n">{rp(G.kolam)}</td></tr>
                <tr><td>Bagianmu<div className="ks-sub">{dasarTeks} dari total {num(G.totalBobot, 0)} seluruh penerima</div></td><td className="r n">{pct(b.porsi)}</td></tr>
                <tr><td>Penerima bonus<div className="ks-sub">bulan ini</div></td><td className="r n">{G.penerima.length} orang</td></tr>
              </tbody>
              <tfoot><tr><td className="r">Diterima tanggal 16</td><td className="r n"><b>{rp(b.service)}</b></td></tr></tfoot>
            </table>
          )}
        </Panel>
      </div>

      <Panel judul="Rincian kehadiran" catatan="Diambil dari jadwal shift yang disusun head divisimu.">
        <div className="ks-komposisi">
          {URUT.map((s) => (
            <div key={s} className="ks-komposisi-sel">
              <div className={"ks-sel-shift " + SHIFT[s].warna} style={{ justifyContent: "center", width: "100%" }}>{s}</div>
              <div className="ks-komposisi-angka n">{b.komposisi[s] || 0}</div>
              <div className="ks-sub">{SHIFT[s].nama}</div>
            </div>
          ))}
        </div>
      </Panel>

      <div className="ks-banner rapat">
        <AlertTriangle size={15} />
        <div>Angka di sini belum dipotong BPJS, PPh 21, dan kasbon. Slip resmi tetap dari finance — halaman ini untuk mengecek apakah hari masuk dan jam lemburmu sudah tercatat benar. Kalau ada yang meleset, kabari head divisimu sebelum tanggal gajian.</div>
      </div>
    </>
  );
}

